import { notFound } from 'next/navigation';
import BackButton from '../../components/BackButton';

type Post = {
  id: number;
  title: string;
  body: string;
  userId: number;
};

type Comment = {
  id: number;
  postId: number;
  name: string;
  email: string;
  body: string;
};

type PageProps = {
  params: Promise<{
    id: string;
  }>;
};

export async function generateMetadata({ params }: PageProps) {
  const { id } = await params;
  try {
    const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`);
    if (!res.ok) return {};
    const post: Post = await res.json();

    return {
      title: `${post.title} - My Blog`,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160),
      },
    };
  } catch (e) {
    return {};
  }
}

export async function generateStaticParams() {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts');
  const posts: Post[] = await res.json();

  return posts.slice(0, 10).map(post => ({
    id: post.id.toString(),
  }));
}

export default async function BlogPost({ params }: PageProps) {
  const { id } = await params;

  let post: Post;
  let comments: Comment[];

  try {
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, { next: { revalidate: 300 } }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, { next: { revalidate: 300 } })
    ]);

    if (!postRes.ok || !commentsRes.ok) {
      notFound();
    }

    post = await postRes.json();
    comments = await commentsRes.json();
  } catch (error) {
    notFound();
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map(comment => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

